def is_grid_symmetric(H, W, S):
    # Check if the grid is symmetric by comparing the first half with the second half
    for i in range(H):
        s = S[i]
        # Check if the i-th row is equal to the reverse of the i-th row in the second half
        if s != S[H - 1 - i][::-1]:
            return False
    return True

