                frog_positions[potential_jumps[0]] += 1
            temp_frogs[i][1] -= frog_positions[temp_frogs[i][0]]
            if temp_frogs[i][1] == 0:
                frogs.append((temp_frogs[i][0], temp_frogs[i][1]))

