import sys

def calculate_xor(sequence):
    xor_value = 0
    for num in sequence:
        xor_value ^= num
    return xor_value

def calculate_kheshtaks(sequence, k):
    xor_value = calculate_xor(sequence)
    k_hash_count = [[0] * (k + 1) for _ in range(1 << (2 * len(sequence) - 1))]
    k_hash_count[0][0] = 1

    for i in reversed(range(len(sequence))):
        current_xor = xor_value ^ (1 << i) ^ (... [xor_value ^ (1 << i), XOR value for more elements])

        for mask in range(1 << (2 * len(sequence) - 1)):
            if mask & current_xor:
                for offset in range(len(sequence) - 1, i, -1):
                    new_mask = mask & ((1 << offset) - 1) & ((1 << i + 1) - 1)
                    if new_mask:
                        k_hash_count[mask ^ new_mask][0] += 1

    k_hash_set = set()
    for mask in range(1 << (2 * len(sequence) - 1)):
        if mask & xor_value:
            k_hash_set.add(k_hash_count[mask][0] if mask not in k_hash_set else 0)

    num_kheshtaks = len(k_hash_set)
    return num_kheshtaks

def query(sequence, query_type, *args):
    if query_type == 1:
        l, r, k = args
        xor_sequence = calculate_xor(sequence[l - 1:r])
        new_mask = xor_sequence | ((1 << (len(sequence) - 1)) - 1)
        k_hash_count = {}
        for i in reversed(range(len(sequence))):
            current_xor = new_mask ^ (1 << i) ^ (... [new_mask ^ (1 << i), XOR value for more elements])
            k_hash_count[current_xor] = k_hash_count.get(current_xor, 0) + 1
        num_kheshtaks = sum(k_hash_count[i] for i in range((1 << (2 * len(sequence) - 1)), 0, -1)) if (1 << (2 * (len(sequence) - 1) + 1)) else 0
        return num_kheshtaks << (2 * (len(sequence) - 1))
    elif query_type == 2:
        l, r = args
        subsequence_xor = calculate_xor(sequence[l - 1:r])
        num_kheshtaks = 0
        for i in range(len(sequence)):
            xor_value = subsequence_xor ^ (1 << i) ^ (... [subsequence_xor ^ (1 << i), XOR value for more elements])
            if xor_value:
                for offset in range(len(sequence) - 1, i, -1):
                    new_xor = xor_value & ((1 << offset) - 1) & ((1 << 2 * len(sequence) - 1 + 1) - 1)
                    if new_xor:
                        num_kheshtaks += calculate_kheshtaks(sequence[l - 1:r], new XOR value) - calculate_kheshtaks(sequence[l - 1:i] + sequence[i + 1: r], new XOR value)
        return num_kheshtaks
    else:
        print("Error: Invalid query type.")
        return -1

def main():
    n, q = map(int, input().split())
    sequence = list(map(int, input().split()))

    for _ in range(q):
        query_type, *args = map(int, input().split())
        result = query(sequence, query_type, *args)
        print(result)

if __name__ == "__main__":
    main()
