    def bfs(graph, s, t):
        queue = []
        queue.append(s)
        seen = {s: -1}  # seed match matrix
        while queue:
            u = queue.pop(0)
            if u == t:
                return seen
            for v, u_cost in graph[u].items():  # for each node
                alt = seen[u] + u_cost
                if v not in seen or alt < seen[v]:
                    seen[v] = seen[u] + u_cost
                    queue.append(v)
        return seen

    parent = {s: None}
    current = s
    visited = set([s])
    while current:
        targets = set(graph[current]) - visited
        if not targets:
            current_choice = -1
        else:
            current_choice = set(target for v, target in sorted(targets.items(), key=lambda x: x[1]))
        # Ensure current_choice exists
        if current_choice:
            if not parent.get(current_choice[0], 0):
                parent[current_choice[0]] = current
            current = current_choice[0]
        visited.add(current)
        if current == t:
            break
    else:
        return []
    # Path and done matching
    current = t
    matching = {t}
    while current:
        matching.add(parent[current])
        current = parent[current]
    if not matching:
