def can_destroy_edges(n, m):
    # Convert input to sets for easy intersection
    edges_set = {(i, j) for i in range(1, n+1) for j in range(i+1, n+1)}
    conn_edges_set = {(i, j) for i in range(1, n+1) for j in range(i, n+1) if i < j}

    if n == 2:
        return 1

    if (n-1) % 2 != 0:
        return 0

    def dfs(node, path=set([])):
        if len(edges_set) == 0:
            return path
        if (len(edges_set) + 1) % 2 != 0:
            return path + {2*len(edges_set) + 1}

        new_path = {}
        for edge in conn_edges_set:
            flags = set(path) - {1}
            if edge[0] in flags:
                new_path[1] = edge
                break
        else:
            return 0

        updated_edges = edges_set - set({new_path[1]})

        # Use mode shift if available
        if m > 0 and (len(updated_edges) + 1) % 2 == 0:
            updated_edges = updated_edges - {new_path[1]}

        updated_path = new_path.copy()
        updated_path[0] = new_path[1] + 2
        updated_path[1] = updated_path[0] + 1

        if len(updated_edges) == 0:
            updated_path[0] = 1
            updated_path[1] = 2

        return dfs(updated_path)

    return max(dfs(), 0)

