    adj = defaultdict(list)
    for x, y in edges:
        adj[x-1].append(y-1)
        adj[y-1].append(x-1)

    def dfs(start, current, mode_flag, visited):
        nonlocal result, current_problem
        if current == result:
            if mode_flag and current_problem:
                return True
            return False

        result = current
        visited.add(current)

        for neighbor in adj[current]:
            if neighbor not in visited:
                if dfs(start, neighbor, mode_flag and current_problem, visited):
                    return True

        if current_problem and not mode_flag:
            return False

        new_visited = visited.copy()
        new_visited.remove(current)
        new_current = neighbor if mode_flag else neighbor + 1

        for neighbor2 in adj[neighbor]:
            if neighbor2 not in new_visited:
                if dfs(start, neighbor2, mode_flag, new_visited):
                    return True

        return False

    mode_flag = 0

    while True:
        if dfs(0, 0, mode_flag, set()):
            return result + 1
        else:
            mode_flag ^= 1

    return 0

