from math import gcd

def find_divisors(n):
    divisors = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
    return sorted(divisors)

def calculate_distance_sum(n, divisors):
    total_distance = 0
    for i in range(n - 1):
        v = gcd(divisors[i + 1], n)
        for u in divisors[:i] + [divisors[i]]:
            total_distance += v // u
    return total_distance

