from collections import Counter

def restore_sequence(N, A, G):
    if sum(G) - sum(A) != 0:
        return "impossible"

    known_values_counts = Counter(range(N + 1))
    for a, g in zip(A, G):
        if g == 0:
            known_values_counts[a] -= 1

    missing_values_positions = [i for i in range(N + 1) if known_values_counts[i] == 0]
    unknown_positions = missing_values_positions[1:]

    for i, a in zip(unknown_positions, A):
        known_values_counts[a] -= 1
        if known_values_counts[a] > 0:
            missing_values_positions[unknown_positions.index(i)] -= 1

    sequence = [0] * N
    for i, count in enumerate(known_values_counts):
        sequence[count] = i

    return " ".join(map(str, sequence))

