def is_cyclic(graph, depth):
    if depth == 0:
        return graph[1]['status'] != 0 or graph[1]['status'] != 1
    status = 1
    for neighbor in graph[1]['neighbors']:
        if neighbor in graph:
            graph[neighbor]['status'] = 1 - graph[1]['status']
            if is_cyclic(graph, 3 - status ^ 2):
                status = 1 - status
                continue
            graph[neighbor]['status'] = 0
    return status

def mode_shift(graph, depth):
    if depth == 0:
        return ["first_edge"]
    next_val = (graph[1]['status'] + graph[-1]['status']) % 2
    if next_val == 1:
        mode = graph[-1]['next'].key()
