import sys

def find_wakanda_cities(n, costs):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def shortest_cost(city, prefix=None, suffix=None):
        if not prefix:
            prefix = []
        if not suffix:
            suffix = []
        visited = set([city])
        min_cost = sys.maxsize
        shortest_pair = None

        for neighbor, cost in enumerate(costs[city-1]):
            if neighbor not in visited:
                visited.add(neighbor)
                current_cost = cost + prefix[neighbor-1] + suffix[neighbor]
                if cost < min_cost:
                    min_cost = cost
                    shortest_pair = (neighbor, prefix[city-1] + suffix[city - neighbor - 1] + cost)
                elif cost == min_cost and current_cost < min_cost:
                    min_cost = current_cost
                    shortest_pair = (neighbor, prefix[city-1] + suffix[city - neighbor - 1] + cost)

                next_prefix = prefix[:]
                next_prefix[city-1] = cost

                next_suffix = suffix[:]
                next_suffix[neighbor] = cost

                shortest_found = shortest_cost(neighbor, next_prefix=next_prefix, suffix=next_suffix)
                if shortest_found or cost < min_cost:
                    if cost == min_cost:
                        min_pair, min_cost = shortest_found
                        break
                    min_cost = cost
                    min_pair = (cost)

        return (city, min_pair) if min_cost else (-1, None)

    max_cost = sys.maxsize
    reachable = set()
    for i in range(n):
        cost, pair = find_wakanda_cities(n - i - 1, costs=costs[:-i-1])
        if not pair[0]:
            pair = -1
        if cost < max_cost and i <= n - 1 - len(reachable):
            reachable.update((i + 1) for i in range(n - i - 1))

    for city in range(1, n + 1):
        cost, new_pair = find_wakanda_cities(n - city, costs=costs[:city-1])
        if not new_pair[0]:
            new_pair = -1
        if cost < max_cost:
            return ([city+reach for reach in reachable + (new_pair,)] if new_pair else [city, -1])

    max_cost = -1
    for pair in reachable:
        cost, new_pair = find_wakanda_cities(n - pair[0] - pair[1] - 2, costs=costs[:pair[0]] + costs[pair[0]:pair[1]] + costs[pair[1]+1:])
        if cost > max_cost:
            max_cost = cost
        elif cost == max_cost and new_pair:
            return reachable[:-1]+(pair,new_pair)

    return reachable+(-1,)

