from collections import defaultdict
import numpy as np

def normalize(A):
    mean = np.mean(A)
    return (A - mean) / np.std(A)

def kheshtaks(sequence):
    dp = defaultdict(int)
    for i in range(len(sequence)):
        dp[sequence[:i+1]] += 1
    return len(dp)

def solve_queries(queries):
    results = []
    for query in queries:
        if query[0] == 1:
            l, r, k = query[1], query[2], query[3]
            sequence = normalize(np.array([sequence[i] for i in range(l-1, r)]))
            results.append(kheshtaks(sequence) ** 2)
        elif query[0] == 2:
            l, r = query[1], query[2]
            sequence = normalize(np.array(sequence[l-1:r]), margin=1)
            results.append(kheshtaks(sequence) ** 2)
    return results

n, q = map(int, input().split())
sequence = list(map(int, input().split()))
queries = [list(map(int, input().split())) for _ in range(q)]
