from typing import List
from collections import defaultdict

def find_min_pairing_cost(n: int, costs: List[List[int]]) -> List[int]:
    result = [-1] * n
    connections = defaultdict(list)

    for i, costs_row in enumerate(costs[1:], 1):  # Skip self-cost
        for j in range(n):
            if costs_row[j]:
                connections[i].append(j)
                connections[j].append(i)

    def is_stable_pairing(cost: List[int]) -> bool:
        for i, city in enumerate(cost):
            if city != -1:
                continue
            if any(cost[j] < cost[i] for j in connections[i]):
                return False
        return True

    min_cost = None
    best_pair = [-1, -1]

    for i in range(n):
        cost = []
        for city in connections[i]:
            cost.append(costs[city].count(city))
        if not cost:
            continue
        cost.sort()
        total_cost = sum(cost)
        if min_cost is None or total_cost < min_cost:
            min_cost = total_cost
            best_pair = [i, cost.index(min(cost))]

    if best_pair[1] == -1:
        return result

    for i in range(n):
        if cost := [costs[best_pair[1]].count(best_pair[0]) - cost for cost in costs[i]]:
            cost.sort()
            total_cost = sum(cost)
            if total_cost == min_cost:
                result[best_pair[0]] = best_pair[1]
                for city, count in enumerate(cost):
                    if count < total_cost - count:  # Ensure min total for this city in this loop
                        result[city + 1] = best_pair[0]

    return result

