def find_occurrences(s, t, k):
    n, m, l = len(s), len(t), len(t)
    dp = [[0] * (l + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(l - 1, -1, -1):
            for p in range(m - i + 1):
                if dp[i + p][j + 1] + 1 < k and t[p] == s[i + p]:
                    dp[i][j] = 1
    count = 0
    for i in range(n - m + 1):
        if dp[i][m] == 1:
            count += 1
    return count

